#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: deploy the Cropstar API and its PostGIS database on Coolify (issue #2).
# Re-runnable: resource ids are remembered in .env.coolify (git-ignored).
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

ENV_FILE="${ENV_FILE:-.env.coolify}"
COOLIFY="https://coolify.cropstar.at"
SITE="https://cropstar.at"
REPO="JohannesPfennigbauer/cropstar"
API_IMAGE="ghcr.io/johannespfennigbauer/cropstar-api"

cd "$(git rev-parse --show-toplevel)"

# uuid_from "pasted text" extracts a Coolify resource UUID from a resource URL or a bare UUID.
uuid_from() {
  local input="${1%/}"
  if [[ "$input" =~ /(application|database|service)/([a-z0-9]+) ]]; then
    printf '%s' "${BASH_REMATCH[2]}"
  else
    printf '%s' "${input##*/}"
  fi
}

# ghcr_api_tags lists the public tags of the API image, or fails if it is not public yet.
ghcr_api_tags() {
  local token
  token=$(curl -fsS "https://ghcr.io/token?scope=repository:johannespfennigbauer/cropstar-api:pull" \
    | python3 -c "import sys, json; print(json.load(sys.stdin)['token'])") || return 1
  curl -fsS -H "Authorization: Bearer $token" \
    "https://ghcr.io/v2/johannespfennigbauer/cropstar-api/tags/list"
}

banner "Cropstar: API and PostGIS on Coolify"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Publish the API image"
say "Pushing main runs the Release workflow, which builds and publishes both images."
say "The Coolify deploy step is skipped until stage 8 sets the webhook, so production"
say "keeps running the current web image."
note "Commits not yet on origin/main:"
git fetch -q origin main
git --no-pager log --oneline origin/main..main | sed 's/^/    /'
if [[ -z "$(git log --oneline origin/main..main)" ]]; then
  note "    (none — main is already pushed)"
elif confirm "Push main to origin now?"; then
  git push origin main
else
  warn "Not pushed. Push main yourself, then re-run this wizard."
  exit 1
fi
open_url "https://github.com/$REPO/actions/workflows/release.yml"
step "Wait until the newest Release run is green (both 'Build and push' jobs)."
pause "Press Enter once the Release run has finished"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Make the API image public"
say "New GHCR packages start private. cropstar-web is public; cropstar-api should match,"
say "so Coolify can pull it without registry credentials."
if ghcr_api_tags >/dev/null 2>&1; then
  note "Already public."
else
  open_url "https://github.com/users/JohannesPfennigbauer/packages/container/cropstar-api/settings"
  step "Scroll to 'Danger Zone' → 'Change visibility' → choose Public → type the name to confirm."
  until ghcr_api_tags >/dev/null 2>&1; do
    pause "Press Enter once the package is public (checking anonymously)"
  done
fi
printf '  %s✓%s %s tags: %s\n' "$GREEN" "$RESET" "$API_IMAGE" "$(ghcr_api_tags)"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Coolify: PostGIS database"
open_url "$COOLIFY/projects"
step "Open project 'cropstar' → its production environment → '+ New' → Databases → PostgreSQL."
step "Pick the same server/destination as the web app; create it."
step "On the database's General page set:"
note "      Name:            cropstar-db"
note "      Image:           postgis/postgis:17-3.5"
note "      Username:        cropstar"
note "      Initial DB:      cropstar"
note "      Password:        keep the generated one"
note "      Public access:   leave private (no public port)"
step "Save, then Start the database and wait until it is 'Running (healthy)'."
ask COOLIFY_DB_UUID "Paste the browser URL of the database page:"
COOLIFY_DB_UUID=$(uuid_from "$COOLIFY_DB_UUID")
write_env COOLIFY_DB_UUID "$COOLIFY_DB_UUID"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Backup: add the database to your dump job"
say "Coolify can only back up to local disk or S3, so this database joins your own"
say "pg_dump job that already ships dumps to the Hetzner Storage Box."
say "Coolify names the database container after its UUID. A matching dump line:"
# shellcheck disable=SC2016 # the $(date) is meant for the user's cron line, not for us
printf '\n    %sdocker exec %s pg_dump -U cropstar -d cropstar -Fc > <your-dump-dir>/cropstar-$(date +%%F).dump%s\n\n' \
  "$BOLD" "$COOLIFY_DB_UUID" "$RESET"
note "Custom format (-Fc) keeps PostGIS types and restores with pg_restore."
note "Check on the server: docker ps --filter name=$COOLIFY_DB_UUID"
step "Add the line to your backup job on the Coolify server."
pause "Press Enter once the dump job includes the new database"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Coolify: API application"
step "Database page → General → copy 'Postgres URL (internal)'. Keep it in the clipboard."
step "In the same environment: '+ New' → Docker Image → image $API_IMAGE, tag latest."
step "Same server/destination as the database and the web app. Then on General:"
note "      Name:              cropstar-api"
note "      Domains:           leave EMPTY (the API is only reached through the web app)"
note "      Ports Exposes:     8000"
note "      Port Mappings:     leave empty"
note "      Network Aliases:   cropstar-api"
step "Environment Variables → add CROPSTAR_DATABASE_URL = the internal Postgres URL (as is)."
step "Health check: path /api/healthz, port 8000 (the image also declares it)."
step "Deploy. In the logs expect 'Running upgrade  -> 0001, Enable PostGIS' and then"
note "      'Uvicorn running on http://0.0.0.0:8000'."
ask COOLIFY_API_UUID "Paste the browser URL of the API application page:"
COOLIFY_API_UUID=$(uuid_from "$COOLIFY_API_UUID")
write_env COOLIFY_API_UUID "$COOLIFY_API_UUID"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Coolify: web application"
say "If cropstar-web already exists in this environment, open it and only add"
say "NUXT_API_BASE_URL below, then redeploy. Otherwise create it:"
step "'+ New' → Docker Image → image ghcr.io/johannespfennigbauer/cropstar-web, tag latest."
step "Same server/destination as the API and the database. Then on General:"
note "      Name:              cropstar-web"
note "      Domains:           https://cropstar.at,https://www.cropstar.at"
note "      Ports Exposes:     3000"
note "      Port Mappings:     leave empty"
step "Environment Variables:"
note "      NUXT_API_BASE_URL          = http://cropstar-api:8000"
note "      NUXT_PUBLIC_I18N_BASE_URL  = $SITE"
step "Health check: path /healthz, port 3000."
step "On cropstar-api add CROPSTAR_PUBLIC_BASE_URL = $SITE (links in reset emails)."
step "Deploy and wait until healthy; the TLS certificate can take a minute or two."
ask COOLIFY_WEB_UUID "Paste the browser URL of the web application page:"
COOLIFY_WEB_UUID=$(uuid_from "$COOLIFY_WEB_UUID")
write_env COOLIFY_WEB_UUID "$COOLIFY_WEB_UUID"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Verify production"
say "Asking $SITE/api/status through the web app's proxy …"
check_status() {
  curl -fsS "$SITE/api/status" | python3 -c '
import json, sys
db = json.load(sys.stdin)["database"]
ok = db["reachable"] and db["postgis_version"]
print("  database reachable:", db["reachable"], "| PostgreSQL", db["postgres_version"], "| PostGIS", db["postgis_version"])
sys.exit(0 if ok else 1)'
}
until check_status; do
  warn "Not healthy yet. Check the API logs in Coolify, the network alias and the env vars."
  pause "Press Enter to check again"
done
printf '  %s✓%s web → API → PostGIS works on %s\n' "$GREEN" "$RESET" "$SITE"
open_url "$SITE/app/status"
step "The status page should show API, database, PostgreSQL and PostGIS in green."
step "In Coolify, confirm the API and the database have no domain and no port mapping."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Auto-deploy from GitHub"
say "The Release workflow redeploys web and API once both images are pushed."
open_url "$COOLIFY/settings/advanced"
step "Settings → Advanced: turn on 'API Access' if it is off."
step "Sidebar → Keys & Tokens → API Tokens: description 'github-release',"
note "      permission 'deploy' only, an expiry you are comfortable with → Create."
ask_secret COOLIFY_TOKEN "Paste the token (hidden; it is not written to disk):"
COOLIFY_WEBHOOK_URL="$COOLIFY/api/v1/deploy?uuid=$COOLIFY_WEB_UUID,$COOLIFY_API_UUID&force=false"
note "Webhook: $COOLIFY_WEBHOOK_URL"
if confirm "Trigger a test deployment of web and API with this token now?"; then
  if curl -fsS -H "Authorization: Bearer $COOLIFY_TOKEN" "$COOLIFY_WEBHOOK_URL" >/dev/null; then
    printf '  %s✓%s Coolify accepted the deployment; watch both Deployments pages.\n' "$GREEN" "$RESET"
  else
    warn "Coolify rejected the request. Check API access, the token permission and the UUIDs."
  fi
fi
set_secret COOLIFY_TOKEN "$COOLIFY_TOKEN"
set_var COOLIFY_WEBHOOK_URL "$COOLIFY_WEBHOOK_URL"
if ! command -v gh >/dev/null 2>&1; then
  say "gh is not installed, so set both by hand:"
  open_url "https://github.com/$REPO/settings/secrets/actions"
  step "Secrets → New repository secret: COOLIFY_TOKEN = the token you just pasted."
  open_url "https://github.com/$REPO/settings/variables/actions"
  step "Variables → New repository variable: COOLIFY_WEBHOOK_URL = the webhook above."
  pause "Press Enter once both are saved"
fi
unset COOLIFY_TOKEN
# ──────────────────────────────────────────────────────────────────────────

finish
